"""Product Repository - Database operations"""
from shared.database import get_db
from typing import List, Optional


class ProductRepository:
    """Handle product database operations."""

    def __init__(self):
        self.db = get_db()

    def list_all(self, limit: int = 20, offset: int = 0) -> List[dict]:
        """List products with pagination."""
        query = """
            SELECT id, name, description, price, image_url, category
            FROM products
            ORDER BY created_at DESC
            LIMIT %s OFFSET %s
        """
        return self.db.fetch_all(query, (limit, offset))

    def get_by_id(self, product_id: str) -> Optional[dict]:
        """Get product by ID."""
        query = "SELECT * FROM products WHERE id = %s"
        return self.db.fetch_one(query, (product_id,))

"""Orders Lambda Handler"""
import json
from shared.response import api_response, error_response
from shared.auth import require_auth
from .repository import OrderRepository
from .stripe import StripePayment

repo = OrderRepository()
payment = StripePayment()


def handler(event, context):
    """Main Lambda handler for order endpoints."""
    path = event.get('path', '')
    method = event.get('httpMethod', 'GET')

    if path == '/orders' and method == 'GET':
        return list_orders(event)
    elif path == '/orders' and method == 'POST':
        return create_order(event)
    elif path.startswith('/orders/') and method == 'GET':
        order_id = path.split('/')[-1]
        return get_order(order_id, event)

    return error_response(404, 'Not found')


@require_auth
def create_order(event):
    """Create a new order with payment."""
    user = event['requestContext']['authorizer']['claims']
    body = json.loads(event.get('body', '{}'))

    # Create payment intent
    payment_intent = payment.create_intent(
        amount=body['total'],
        customer_email=user['email']
    )

    # Create order
    order = repo.create(
        user_id=user['sub'],
        items=body['items'],
        payment_intent_id=payment_intent['id']
    )

    return api_response(order)

"""Stripe Payment Integration"""
import stripe
import os

stripe.api_key = os.environ['STRIPE_SECRET_KEY']


class StripePayment:
    """Stripe payment wrapper."""

    def create_intent(self, amount: int, customer_email: str) -> dict:
        """Create a payment intent."""
        intent = stripe.PaymentIntent.create(
            amount=amount,
            currency='usd',
            receipt_email=customer_email,
            automatic_payment_methods={'enabled': True}
        )
        return {
            'id': intent.id,
            'client_secret': intent.client_secret
        }

"""Standardized API Response Utilities"""
import json
from typing import Any


def api_response(data: Any, status_code: int = 200) -> dict:
    """Create a standardized API response."""
    return {
        'statusCode': status_code,
        'headers': {
            'Content-Type': 'application/json',
            'Access-Control-Allow-Origin': '*',
            'Access-Control-Allow-Credentials': True
        },
        'body': json.dumps(data)
    }


def error_response(status_code: int, message: str) -> dict:
    """Create an error response."""
    return api_response({'error': message}, status_code)

"""Authentication Middleware"""
import functools
from .response import error_response


def require_auth(func):
    """Decorator to require authentication."""
    @functools.wraps(func)
    def wrapper(event, *args, **kwargs):
        claims = event.get('requestContext', {}).get('authorizer', {}).get('claims')
        if not claims:
            return error_response(401, 'Unauthorized')
        return func(event, *args, **kwargs)
    return wrapper

